// Settings come from n8n Variables; self-hosted community installs without
// Variables fall back to environment variables of the same name.
function setting(name) {
  if ($vars?.[name]) return $vars[name];
  try { return $env[name]; } catch (error) { return undefined; }
}

// Verifies the HMAC from Convex before anything else runs. Secret: n8n Variable
// LENDLOOP_OUTBOUND_SECRET (same value as Convex env N8N_OUTBOUND_SECRET).
const crypto = require('crypto');

const MAX_SKEW_SECONDS = 300;
const secret = setting('LENDLOOP_OUTBOUND_SECRET');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

// Raw body (Webhook option "Raw Body") so we hash exactly the bytes Convex signed.
let raw = null;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  // Re-serializing item.json.body would not match the signed bytes.
}

const path = new URL(item.json.webhookUrl).pathname;

function check() {
  if (!secret) return 'not configured';
  if (raw === null) return 'no raw body (enable the Webhook "Raw Body" option)';
  if (!timestamp || !signature.startsWith('v1=')) return 'missing signature';
  const seconds = Number(timestamp);
  if (!Number.isInteger(seconds)) return 'malformed timestamp';
  if (Math.abs(Date.now() / 1000 - seconds) > MAX_SKEW_SECONDS) return 'stale';
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.POST.${path}.${raw}`)
    .digest();
  const given = Buffer.from(signature.slice(3), 'hex');
  if (given.length !== expected.length) return 'mismatch';
  return crypto.timingSafeEqual(given, expected) ? null : 'mismatch';
}

const reason = check();
if (reason) {
  return [{ json: { valid: false, reason } }];
}

// Pass on only the verified payload; headers and raw body stop here.
return [{ json: { valid: true, payload: JSON.parse(raw) } }];

// One short email per event, using only fields in the minimized payload.
const p = $input.first().json.payload;
const who = p.recipient.firstName;
const other = p.counterpartFirstName;
const tool = p.toolName;
const dates = p.loan.startDate === p.loan.endDate
  ? p.loan.startDate
  : `${p.loan.startDate} to ${p.loan.endDate}`;

const copy = {
  'request.created': [
    `${other} would like to borrow your ${tool}`,
    `${other} asked to borrow your ${tool} for ${dates}. Approve or decline it here:`,
  ],
  'request.approved': [
    `Your request for ${tool} was approved`,
    `${other} approved your request to borrow the ${tool} for ${dates}. Details:`,
  ],
  'request.declined': [
    `Your request for ${tool} was declined`,
    `Your request to borrow the ${tool} for ${dates} was declined. Find something else here:`,
  ],
  'request.cancelled': [
    `A loan for ${tool} was cancelled`,
    `The loan of the ${tool} for ${dates} was cancelled. See your loans here:`,
  ],
  'loan.returned': [
    `Thanks for returning the ${tool}`,
    `${other} marked the ${tool} as returned. Thanks for borrowing responsibly!`,
  ],
};
const [subject, intro] = copy[p.event] || [`LendLoop update about ${tool}`, 'See your loans here:'];

return [{
  json: {
    eventId: p.eventId,
    to: p.recipient.email,
    subject,
    text: `Hi ${who},\n\n${intro}\n${p.appUrl}\n\n- LendLoop`,
  },
}];

// Tell Convex whether retrying can help: provider outages and rate limits can,
// a rejected address or payload (4xx) cannot.
const error = $input.first().json.error || {};
const text = `${error.httpCode || ''} ${error.message || ''} ${error.description || ''}`;
const status = Number((text.match(/(?:^|\D)([45]\d\d)(?:\D|$)/) || [])[1]) || 0;
const retryable = status === 0 || status >= 500 || status === 408 || status === 429;
return [{ json: { retryable, status } }];
